<script setup>
import {ElButton,ElInput,ElFormItem,ElSwitch,ElSelect,ElOption,ElAlert} from 'element-plus';
const props=defineProps({content:{type:Object,required:true},disabled:Boolean,language:String,eventId:Number});
const t=(zh,en)=>props.language==='en'?en:zh;
const emit=defineEmits(['remove','move']);
const collections=[
 {key:'topics',singular:['主题','topic'],title:['征稿范围与主题','Topics & scope'],fields:[{key:'title',label:['主题分组','Topic group'],limit:300},{key:'keywords',label:['关键词（每行一个）','Keywords (one per line)'],limit:5000,multiline:true}]},
 {key:'industry',singular:['产业方向','industry direction'],title:['地方产业与技术需求','Local industry & technology needs'],fields:[{key:'title',label:['重点产业方向','Industry direction'],limit:300},{key:'description',label:['技术背景、需求与内容介绍','Background, needs & introduction'],limit:5000,multiline:true},{key:'goal',label:['技术目标','Technical goals'],limit:5000,multiline:true},{key:'cooperation',label:['合作方式','Cooperation models'],limit:5000,multiline:true}]}
];
const choices=[
 {key:'showcase',title:['科技成果展示与征集','Research showcase'],items:[['论文与报告','Papers & presentations'],['学术海报展示','Academic posters'],['科技成果展板','Research display panels'],['成果路演','Research pitches'],['实物或样机展示','Products & prototypes'],['软件或系统演示','Software & system demos'],['线上成果展示','Online showcase'],['产业合作对接','Industry matchmaking'],['暂不确定','To be confirmed']]},
 {key:'audience',title:['参会对象','Who should attend'],items:[['高校/科研院所','Universities & research institutes'],['企业技术负责人','Industry technology leaders'],['产业园区与协会','Industry parks & associations'],['投资与服务机构','Investors & service providers']]},
 {key:'highlights',title:['会议亮点','Conference highlights'],items:[['高水平专家交流','Expert exchange'],['精准供需对接','Targeted matchmaking'],['期刊合作与论文交流','Journals & paper exchange'],['企业及产业园区参访','Company & industry park visits'],['地方特色产业聚焦','Regional industry focus'],['企业技术需求发布','Industry technology needs'],['科技成果转化与项目落地','Research commercialization'],['多形式科技成果展示','Research showcase formats'],['人才引进与研发合作','Talent & R&D collaboration'],['科技金融与投融资对接','Finance & investment matchmaking']]}
];
const activities=[['企业技术需求发布','Industry technology needs'],['专题论坛','Thematic forums'],['科技成果产业推介','Research-to-industry pitches'],['一对一预约洽谈','One-to-one meetings'],['企业及产业园区参访','Company & industry park visits']];
function add(collection){const item={enabled:true};for(const field of collection.fields){item[field.key]='';item[field.key+'_en']='';}props.content[collection.key].push(item);}
function addCommittee(){props.content.committees.push({title:'',title_en:'',enabled:true,members:[]});}
function addMember(group){group.members.push({name:'',name_en:'',affiliation:'',affiliation_en:'',enabled:true});}
</script>

<template>
 <section class="surface site-editor-section" id="editor-committees" data-test="committees-editor">
  <div class="site-section-title"><div><h3>{{t('会议组织及成员','Committees & members')}}</h3><p>{{t('分别添加大会主席、程序委员会等组织，再维护各组织成员。','Add groups such as chairs and program committees, then add their members.')}}</p></div><ElButton data-test="add-committee" :disabled="disabled||content.committees.length>=20" @click="addCommittee">{{t('添加组织','Add committee')}}</ElButton></div>
  <p v-if="!content.committees.length" class="site-empty">{{t('尚未添加组织。','No committees yet.')}}</p>
  <article v-for="(group,index) in content.committees" :key="index" class="site-list-item" data-test="committee-item">
   <div class="site-item-toolbar"><strong>{{group.title||t('新组织','New committee')}}</strong><div><ElSwitch v-model="group.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||index===0" @click="emit('move',content.committees,index,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||index===content.committees.length-1" @click="emit('move',content.committees,index,1)">{{t('下移','Move down')}}</ElButton><ElButton type="danger" plain :disabled="disabled" @click="emit('remove',content.committees,index)">{{t('删除','Remove')}}</ElButton></div></div>
   <ElFormItem :label="t('组织名称','Committee name')"><ElInput v-model="group.title" maxlength="300"/></ElFormItem><details class="site-english"><summary>{{t('英文组织名称（可选）','English name (optional)')}}</summary><ElInput v-model="group.title_en" maxlength="300" aria-label="Committee name (English)"/></details>
   <div v-for="(member,mi) in group.members" :key="mi" class="site-organization-item">
    <div class="site-item-toolbar"><strong>{{t('成员','Member')}} {{mi+1}}</strong><div><ElSwitch v-model="member.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||mi===0" @click="emit('move',group.members,mi,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||mi===group.members.length-1" @click="emit('move',group.members,mi,1)">{{t('下移','Move down')}}</ElButton><ElButton :disabled="disabled" type="danger" plain @click="emit('remove',group.members,mi)">{{t('删除','Remove')}}</ElButton></div></div>
    <div class="site-fields"><ElFormItem :label="t('姓名与职称','Name & title')"><ElInput v-model="member.name" maxlength="500"/></ElFormItem><ElFormItem :label="t('头衔、所属单位及来源国','Honors, affiliation & country')"><ElInput v-model="member.affiliation" maxlength="500"/></ElFormItem></div>
    <details class="site-english"><summary>{{t('英文成员信息（可选）','English member information (optional)')}}</summary><div class="site-fields"><ElFormItem label="Name & title (English)"><ElInput v-model="member.name_en" maxlength="500"/></ElFormItem><ElFormItem label="Affiliation & country (English)"><ElInput v-model="member.affiliation_en" maxlength="500"/></ElFormItem></div></details>
   </div><ElButton :disabled="disabled||group.members.length>=100" @click="addMember(group)">{{t('添加成员','Add member')}}</ElButton>
  </article>
 </section>

 <section v-for="collection in collections" :key="collection.key" class="surface site-editor-section" :id="`editor-${collection.key}`">
  <div class="site-section-title"><div><h3>{{t(...collection.title)}}</h3><p v-if="collection.key==='industry'">{{t('仅填写产业方向及技术需求，不填写具体企业名称、联系人、网址或提交入口。合作方式可填写联合研发、技术许可、咨询、样机测试、委托开发等。','Describe sectors and technology needs. Do not include company names, contacts, URLs or submission links.')}}</p></div><ElButton :data-test="`add-${collection.key==='topics'?'topic':'industry'}`" :disabled="disabled||content[collection.key].length>=30" @click="add(collection)">{{t('添加','Add ')}}{{t(...collection.singular)}}</ElButton></div>
  <p v-if="!content[collection.key].length" class="site-empty">{{t('尚未添加内容。','No items yet.')}}</p>
  <article v-for="(item,index) in content[collection.key]" :key="index" class="site-list-item">
   <div class="site-item-toolbar"><strong>{{t(...collection.singular)}} {{index+1}}</strong><div><ElSwitch v-model="item.enabled" :active-text="t('显示','Show')"/><ElButton :disabled="disabled||index===0" @click="emit('move',content[collection.key],index,-1)">{{t('上移','Move up')}}</ElButton><ElButton :disabled="disabled||index===content[collection.key].length-1" @click="emit('move',content[collection.key],index,1)">{{t('下移','Move down')}}</ElButton><ElButton type="danger" plain :disabled="disabled" @click="emit('remove',content[collection.key],index)">{{t('删除','Remove')}}</ElButton></div></div>
   <ElFormItem v-for="field in collection.fields" :key="field.key" :label="t(...field.label)" :data-test="`${collection.key}-${field.key}`"><ElInput v-model="item[field.key]" :type="field.multiline?'textarea':'text'" :rows="field.multiline?4:undefined" :maxlength="field.limit" show-word-limit/></ElFormItem>
   <details class="site-english"><summary>{{t('英文内容（可选）','English content (optional)')}}</summary><ElFormItem v-for="field in collection.fields" :key="field.key" :label="field.label[1]+' (English)'"><ElInput v-model="item[field.key+'_en']" :type="field.multiline?'textarea':'text'" :rows="field.multiline?4:undefined" :maxlength="field.limit" show-word-limit/></ElFormItem></details>
  </article>
  <template v-if="collection.key==='topics'"><ElFormItem :label="t('主题咨询与备注','Scope enquiries & notes')"><ElInput v-model="content.topic_note" type="textarea" :rows="3" maxlength="2000" :placeholder="t('不确定论文是否符合主题？请填写咨询方式。','Add contact details for authors who are unsure whether their work fits.')"/></ElFormItem><details class="site-english"><summary>{{t('英文备注（可选）','English notes (optional)')}}</summary><ElInput v-model="content.topic_note_en" type="textarea" maxlength="2000"/></details></template>
 </section>

 <section v-for="choice in choices" :key="choice.key" class="surface site-editor-section" :id="`editor-${choice.key}`" :data-test="`choices-${choice.key}`"><div class="site-section-title"><div><h3>{{t(...choice.title)}}</h3><p>{{t('可多选和移除，选中项目将在首页并列展示。请在“首页模块”中开启对应模块。','Select multiple items to display as cards. Enable the corresponding homepage section above.')}}</p></div></div><ElFormItem :label="t(...choice.title)"><ElSelect v-model="content[choice.key]" multiple filterable :disabled="disabled"><ElOption v-for="item in choice.items" :key="item[0]" :value="item[0]" :label="t(...item)"/></ElSelect></ElFormItem></section>

 <section class="surface site-editor-section" id="editor-matchmaking" data-test="matchmaking-editor"><div class="site-section-title"><div><h3>{{t('产业对接活动与意向登记','Industry matchmaking & expressions of interest')}}</h3><p>{{t('介绍活动安排；登记信息仅供本会议管理者查看和导出。','Describe the activities. Submitted information is available only to conference managers.')}}</p></div><ElSwitch v-model="content.matchmaking.enabled" :active-text="t('启用登记','Enable interest forms')"/></div><ElFormItem :label="t('活动形式','Activities')"><ElSelect v-model="content.matchmaking.activities" multiple filterable><ElOption v-for="item in activities" :key="item[0]" :value="item[0]" :label="t(...item)"/></ElSelect></ElFormItem><ElFormItem :label="t('活动介绍','Activity introduction')"><ElInput v-model="content.matchmaking.text" type="textarea" :rows="5" maxlength="10000" show-word-limit/></ElFormItem><details class="site-english"><summary>{{t('英文活动介绍（可选）','English introduction (optional)')}}</summary><ElInput v-model="content.matchmaking.text_en" type="textarea" :rows="5" maxlength="10000" show-word-limit/></details><p class="site-native-links"><a :href="`/event/${eventId}/interest/`" target="_blank" rel="noopener">{{t('预览意向登记','Preview interest forms')}}</a><a :href="`/event/${eventId}/manage/registration/`" target="_blank" rel="noopener">{{t('查看登记与导出','View submissions & export')}}</a></p></section>
</template>
